from pathlib import Path
import re,json
src=Path('world-pixi-v10.js').read_text()

# Track persistent wildlife sprites in the same depth-sorted world as people and objects.
src=src.replace("const agentSprites=new Map(),pointers=new Map(),selectables=new Map();", "const agentSprites=new Map(),wildlifeSprites=new Map(),pointers=new Map(),selectables=new Map();",1)
src=src.replace("worldItems=[];agentSprites.clear();selection=null}","worldItems=[];agentSprites.clear();wildlifeSprites.clear();selection=null}",1)
src=src.replace("version:'v8-spatial-depth'","version:'v11-living-basin'",1)

# Smooth, extended creek: canonical control points remain authoritative, renderer interpolates them.
creek=r'''function creekCurve(points,steps=14){if(points.length<2)return points;const p=[{x:points[0].x-(points[1].x-points[0].x)*.42,y:points[0].y-(points[1].y-points[0].y)*.42},...points,{x:points.at(-1).x+(points.at(-1).x-points.at(-2).x)*.42,y:points.at(-1).y+(points.at(-1).y-points.at(-2).y)*.42}],out=[];for(let i=1;i<p.length-2;i++){const p0=p[i-1],p1=p[i],p2=p[i+1],p3=p[i+2];for(let s=0;s<steps;s++){const t=s/steps,t2=t*t,t3=t2*t;out.push({x:.5*((2*p1.x)+(-p0.x+p2.x)*t+(2*p0.x-5*p1.x+4*p2.x-p3.x)*t2+(-p0.x+3*p1.x-3*p2.x+p3.x)*t3),y:.5*((2*p1.y)+(-p0.y+p2.y)*t+(2*p0.y-5*p1.y+4*p2.y-p3.y)*t2+(-p0.y+3*p1.y-3*p2.y+p3.y)*t3)})}}out.push(points.at(-1));return out}
function drawCreek(){const creek=(current.worldModel.objects||[]).find(o=>o.type==='creek_segment');if(!creek?.geometry?.points)return;let pts=creek.geometry.points.map(([x,y])=>wp({x,y}));const first=pts[0],second=pts[1],last=pts.at(-1),prev=pts.at(-2);pts=[{x:first.x-(second.x-first.x)*.8,y:first.y-(second.y-first.y)*.8},...pts,{x:last.x+(last.x-prev.x)*.8,y:last.y+(last.y-prev.y)*.8}];const smooth=creekCurve(pts,12),depth=current.worldModel?.fields?.waterDepth?.objects?.[creek.id]??.42,baseWidth=48+depth*20;const bank=new PIXI.Graphics();bank.lineStyle(baseWidth+27,mix(C.bank,C.mud,.28),.92).moveTo(smooth[0].x,smooth[0].y);smooth.slice(1).forEach((p,i)=>bank.lineTo(p.x,p.y));terrain.addChild(bank);const water=new PIXI.Graphics();water.lineStyle(baseWidth,mix(C.water,C.waterDark,depth*.35),.98).moveTo(smooth[0].x,smooth[0].y);smooth.slice(1).forEach(p=>water.lineTo(p.x,p.y));terrain.addChild(water);const shine=new PIXI.Graphics();shine.lineStyle(Math.max(2,baseWidth*.09),0xc5e7e6,.12).moveTo(smooth[0].x,smooth[0].y-4);smooth.slice(1).forEach(p=>shine.lineTo(p.x,p.y-4));terrain.addChild(shine);const R=rng('creek-v11');for(let i=7;i<smooth.length-7;i+=Math.max(5,Math.round(7+R()*8))){const a=smooth[i],z=3+R()*5,x=a.x+(R()-.5)*baseWidth*.68,y=a.y+(R()-.5)*baseWidth*.55;const rock=new PIXI.Graphics();rock.beginFill(R()>.5?C.rock:C.rock2,.82).drawEllipse(x,y,z,z*.62).endFill();terrain.addChild(rock)}}'''
src,n=re.subn(r"function drawCreek\(\)\{.*?\}\nfunction makeSelectable",creek+"\nfunction makeSelectable",src,count=1,flags=re.S)
if n!=1:raise SystemExit('creek function anchor not found')

# Canonical wildlife sprites and continuous heartbeat interpolation.
wild=r'''function wildlifePos(a){const m=a.movement||{},from=m.from||a.previousPosition||a.position,to=m.to||a.position,q=progress();return{x:from.x+(to.x-from.x)*q,y:from.y+(to.y-from.y)*q}}
function animalGraphics(a){const c=new PIXI.Container(),g=new PIXI.Graphics(),species=a.species;let h=28;if(species==='deer'){g.beginFill(0x8b6848,.98).drawEllipse(0,0,17,9).drawCircle(16,-8,6).endFill();g.lineStyle(3,0x644832,1).moveTo(-10,6).lineTo(-11,19).moveTo(8,6).lineTo(10,19).moveTo(15,-13).lineTo(11,-21).moveTo(18,-13).lineTo(22,-21);g.beginFill(0xd9c7a6,.75).drawCircle(-17,-1,3).endFill();if(/buck/i.test(a.label||''))g.lineStyle(1.5,0x5a412f,.9).moveTo(18,-13).lineTo(14,-21).moveTo(18,-15).lineTo(23,-22);h=42}else if(species==='rabbit'){g.beginFill(0x8f8779,.98).drawEllipse(0,3,10,7).drawCircle(8,-4,6).endFill();g.beginFill(0xaaa292,.98).drawEllipse(6,-14,2.5,8).drawEllipse(11,-13,2.5,8).endFill();g.beginFill(0xe7dfd0,.9).drawCircle(-10,2,3).endFill();h=28}else if(species==='bear'){g.beginFill(0x44382f,.99).drawEllipse(0,1,21,13).drawCircle(17,-5,9).drawCircle(13,-13,3).drawCircle(21,-13,3).endFill();g.lineStyle(5,0x342b25,1).moveTo(-10,9).lineTo(-11,20).moveTo(10,9).lineTo(12,20);h=38}else if(species==='fish'){g.beginFill(0x527f87,.95).drawEllipse(0,0,11,4).drawPolygon([-10,0,-17,-6,-17,6]).endFill();g.beginFill(0xb9d7d2,.7).drawCircle(6,-1,1).endFill();h=10}else{g.beginFill(0x776f61,.9).drawCircle(0,0,8).endFill();h=18}c.addChild(g);const name=new PIXI.Text(a.label||species,{fontFamily:'Arial',fontSize:10,fontWeight:'600',fill:0xf2f4e9,stroke:0x08100b,strokeThickness:3});name.anchor.set(.5);name.y=species==='deer'?-30:species==='bear'?-25:-20;name.alpha=0;c.addChild(name);c._animal={g,name};c.eventMode='static';c.cursor='pointer';c.on('pointerover',()=>name.alpha=.9);c.on('pointerout',()=>name.alpha=0);c.on('pointertap',e=>{e.stopPropagation();showSelection(c);openInspector(a,'wildlife')});return{c,h}}
function renderWildlife(){for(const a of current.ecologySystem?.wildlife||[]){if(!a.active)continue;const made=animalGraphics(a),p=wp(a.position);made.c.position.set(p.x,p.y);made.c._data=a;addWorld(made.c,p.y,7,{kind:`wildlife-${a.species}`,tier:'wildlife',sourceId:a.id,height:made.h});wildlifeSprites.set(a.id,made.c)}}
function updateWildlife(t){const q=progress();for(const a of current.ecologySystem?.wildlife||[]){const c=wildlifeSprites.get(a.id);if(!c)continue;const p=wp(wildlifePos(a)),moving=Math.hypot((a.movement?.to?.x||a.position.x)-(a.movement?.from?.x||a.position.x),(a.movement?.to?.y||a.position.y)-(a.movement?.from?.y||a.position.y))>.4;c.position.set(p.x,p.y);c.zIndex=worldZ(p.y,7);if(c._debug){c._debug.screenX=p.x;c._debug.screenBaseY=p.y;c._debug.zIndex=c.zIndex}const g=c._animal?.g;if(g){g.y=moving?Math.sin(t*(a.species==='rabbit'?9:a.species==='deer'?6:3)+hash(a.id)%7)*1.3:Math.sin(t*2+hash(a.id)%5)*.35;if(a.species==='fish')g.rotation=Math.sin(t*2+hash(a.id)%11)*.08}c._animal.name.scale.set(1/camera.scale)}}'''
src=src.replace("function progress(){",wild+"\nfunction progress(){",1)

# Render wildlife after canonical terrain/objects/artifacts are created.
old="(current.artifacts||[]).filter(a=>a.status==='active'||a.status==='remnant').forEach(drawArtifact)}"
new="(current.artifacts||[]).filter(a=>a.status==='active'||a.status==='remnant').forEach(drawArtifact);renderWildlife()}"
if old not in src:raise SystemExit('renderWorld wildlife anchor not found')
src=src.replace(old,new,1)

# Animate wildlife every frame.
src=src.replace("}resolveAgentLabels();const wind=", "}updateWildlife(t);resolveAgentLabels();const wind=",1)

# Wildlife inspector.
old="function openInspector(d,k){const panel=$('#inspector');if(!panel)return;$('#inspectType').textContent=k==='agent'?'AUTONOMOUS AGENT':k==='artifact'?'PERSISTENT ARTIFACT':'CANONICAL WORLD OBJECT';$('#inspectTitle').textContent=d.name||d.label||d.id;$('#inspectBody').innerHTML=k==='agent'?agentInspector(d):k==='artifact'?artifactInspector(d):objectInspector(d);panel.classList.add('open')}"
new="function openInspector(d,k){const panel=$('#inspector');if(!panel)return;$('#inspectType').textContent=k==='agent'?'AUTONOMOUS AGENT':k==='wildlife'?'LIVING WILDLIFE':k==='artifact'?'PERSISTENT ARTIFACT':'CANONICAL WORLD OBJECT';$('#inspectTitle').textContent=d.name||d.label||d.id;$('#inspectBody').innerHTML=k==='agent'?agentInspector(d):k==='wildlife'?wildlifeInspector(d):k==='artifact'?artifactInspector(d):objectInspector(d);panel.classList.add('open')}"
if old not in src:raise SystemExit('inspector anchor not found')
src=src.replace(old,new,1)
anchor="function agentInspector(a){"
wildinspect="function wildlifeInspector(a){const n=a.needs||{},ai=a.ai||{};return `<div class=\"kv\"><span>ID</span><b>${esc(a.id)}</b><span>Species</span><b>${esc(a.species)}</b><span>Behavior</span><b>${esc(a.behavior||'—')}</b><span>Activity</span><b>${esc(a.activity||'—')}</b><span>Fear</span><b>${Math.round(a.fear||0)}%</b><span>Energy</span><b>${Math.round(n.energy||0)}%</b><span>Hunger</span><b>${Math.round(n.hunger||0)}%</b><span>Thirst</span><b>${Math.round(n.thirst||0)}%</b><span>Mind</span><b>${esc(ai.mode||'simulation')}</b></div>`}\n"
src=src.replace(anchor,wildinspect+anchor,1)

# World Pulse context drawer.
pulse=r'''function pulseTab(name){document.querySelectorAll('[data-pulse-tab]').forEach(b=>b.classList.toggle('active',b.dataset.pulseTab===name));document.querySelectorAll('.pulsePanel').forEach(p=>p.classList.toggle('active',p.dataset.pulsePanel===name))}
function pct(v){return clamp(Math.round(Number(v)||0),0,100)}
function stat(label,value){return `<div class="pulseStat"><span>${esc(label)}</span><b>${esc(value)}</b></div>`}
function renderPulse(){if(!current)return;const animals=(current.ecologySystem?.wildlife||[]).filter(x=>x.active),ambient=current.ecologySystem?.ambient||{},[a,b]=current.agents,rel=current.relationships?.[[a?.id,b?.id].filter(Boolean).sort().join('|')]||{},usage=current.meta?.aiUsage||{},dna=current.dna||[],discoveries=current.discoveries||[];const intro=`<div class="pulseCard"><small>WHAT THIS IS</small><h3>A persistent world, not a scripted story.</h3><p>Physics and ecology set the constraints. Mara and Ivo perceive, remember and decide what happens inside them. Wildlife exists as canonical simulation state; AI wildlife is optional.</p></div>`;const wild=animals.map(x=>`<span class="wildlifeChip"><i></i>${esc(x.label)} · ${esc(x.behavior||x.activity)}</span>`).join('');$('#pulseNow').innerHTML=intro+`<div class="pulseGrid">${stat('Day',current.day)}${stat('Wildlife',animals.length)}${stat('Bird activity',ambient.birds??0)}${stat('Fish activity',ambient.fishActivity??0)}</div><div class="pulseCard"><small>LIVING BASIN</small><h3>What else is moving</h3><p>${wild||'Wildlife state is initializing.'}</p></div>`+(current.liveThreads||[]).slice(0,3).map(x=>`<div class="pulseCard"><small>${esc(x.kind)} · urgency ${x.urgency}</small><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p></div>`).join('');$('#pulseAgents').innerHTML=(current.agents||[]).map(x=>`<div class="pulseCard"><small>${esc(x.mind?.brainMode||'fallback').toUpperCase()} MIND · ${esc(x.position)}</small><h3>${esc(x.name)} — ${esc(x.mind?.currentGoal||x.currentAction)}</h3><p>${esc(x.mind?.intent||x.currentAction||'')}</p><div class="pulseGrid">${stat('Hydration',pct(x.needs?.hydration)+'%')}${stat('Satiety',pct(x.needs?.hunger)+'%')}${stat('Energy',pct(x.needs?.energy)+'%')}${stat('Warmth',pct(x.needs?.warmth)+'%')}</div></div>`).join('');$('#pulseRelationship').innerHTML=`<div class="pulseCard"><small>MARA ↔ IVO</small><h3>${rel.familiarity>55?'Familiar partners':rel.familiarity>25?'Learning each other':'Still new to each other'}</h3><div class="pulseGrid">${stat('Trust',pct(rel.trust)+'%')}${stat('Familiarity',pct(rel.familiarity)+'%')}${stat('Affinity',pct(rel.affinity)+'%')}${stat('Shared memories',rel.sharedMemories||0)}</div></div><div class="pulseCard"><small>CULTURE</small><p>${rel.techniquesShared||0} techniques have been explicitly shared. Their relationship changes through actual interactions rather than a scripted progression track.</p></div>`;$('#pulseDiscoveries').innerHTML=discoveries.length?discoveries.slice(0,10).map(x=>`<div class="pulseCard"><small>DAY ${x.day} · ${esc(x.firstAgentName||'world')}</small><h3>${esc(x.title)}</h3><p>${esc(x.detail||x.effect||'')}</p></div>`).join(''):'<div class="pulseCard"><p>No recorded world firsts yet.</p></div>';$('#pulseDNA').innerHTML=dna.length?dna.slice(0,6).map(x=>`<div class="pulseCard"><small>${esc(x.agent_name)} · ${esc(x.mind?.brain_mode||'fallback')} · ${esc(x.decision_id)}</small><h3>${esc(x.action_label||x.action)}</h3><p>${esc(x.mind?.decision_summary||'Decision trace recorded.')}</p><small>${(x.retrieved_memories||[]).length} retrieved memories · ${(x.mind?.referenced_memory_ids||[]).length} explicitly referenced</small></div>`).join(''):'<div class="pulseCard"><p>No Decision DNA traces yet.</p></div>';const people=current.settings?.ai?.people||{},wa=current.settings?.ai?.wildlife||{};$('#pulseControls').innerHTML=`<div class="pulseCard"><small>AI RUNTIME</small><h3>Spend model calls where they matter.</h3><div class="aiControl"><div><b>Mara AI mind</b><small>Falls back to deterministic policy when off</small></div><label class="switch"><input data-ai="agent-mara" type="checkbox" ${people['agent-mara']!==false?'checked':''}><span></span></label></div><div class="aiControl"><div><b>Ivo AI mind</b><small>Falls back to deterministic policy when off</small></div><label class="switch"><input data-ai="agent-ivo" type="checkbox" ${people['agent-ivo']!==false?'checked':''}><span></span></label></div><div class="aiControl"><div><b>Wildlife AI escalation</b><small>OFF = continuous deterministic ecology only</small></div><label class="switch"><input data-ai="wildlife" type="checkbox" ${wa.enabled?'checked':''}><span></span></label></div><div class="usageLine"><span>Total model calls</span><b>${usage.calls||0}</b></div><div class="usageLine"><span>Input tokens</span><b>${Number(usage.inputTokens||0).toLocaleString()}</b></div><div class="usageLine"><span>Output tokens</span><b>${Number(usage.outputTokens||0).toLocaleString()}</b></div><div class="usageLine"><span>Reasoning tokens</span><b>${Number(usage.reasoningTokens||0).toLocaleString()}</b></div><div class="ownerNote" id="ownerControlNote">Owner switches update the canonical control file. First use asks for your private control key and stores it only in this browser.</div></div>`}
async function changeAIControl(el){const people={},body={};if(el.dataset.ai==='wildlife')body.wildlifeEnabled=el.checked;else people[el.dataset.ai]=el.checked;if(Object.keys(people).length)body.people=people;let key=localStorage.getItem('chatgptfarm-control-key');if(!key){key=prompt('Owner control key');if(!key){el.checked=!el.checked;return}localStorage.setItem('chatgptfarm-control-key',key)}const note=$('#ownerControlNote');if(note)note.textContent='Updating canonical controls…';try{const r=await fetch('/api/control',{method:'POST',headers:{'Content-Type':'application/json','X-Control-Key':key},body:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw Error(data.error||String(r.status));current.settings||={};current.settings.ai=data.control.ai;renderPulse();if(note)note.textContent='Saved. The next world heartbeat will use this setting.'}catch(e){el.checked=!el.checked;if(note)note.textContent=e.message==='owner_controls_not_configured'?'Owner controls need CONTROL_KEY + GITHUB_CONTROL_TOKEN in Vercel once; current safe defaults remain active.':`Control update failed: ${e.message}`;if(e.message==='unauthorized')localStorage.removeItem('chatgptfarm-control-key')}}'''
src=src.replace("function wireUI(){",pulse+"\nfunction wireUI(){",1)

# Replace wireUI to include Pulse controls while retaining all camera/touch behavior.
wire=r'''function wireUI(){document.querySelectorAll('[data-camera]').forEach(b=>b.addEventListener('click',()=>{const m=b.dataset.camera;if(m==='auto')frameActivity(true);else{camera.mode=m;camera.manualUntil=0;camera.scale=Math.max(camera.scale,1.45);syncButtons();updateCamera(true)}}));$('#zoomIn')?.addEventListener('click',()=>zoomAt({x:app.screen.width/2,y:app.screen.height/2},camera.scale*1.2));$('#zoomOut')?.addEventListener('click',()=>zoomAt({x:app.screen.width/2,y:app.screen.height/2},camera.scale/1.2));$('#fitWorld')?.addEventListener('click',()=>frameActivity(true));$('#closeInspector')?.addEventListener('click',()=>$('#inspector').classList.remove('open'));$('.threadTop')?.addEventListener('click',()=>$('.threadPanel')?.classList.toggle('expanded'));$('#pulseButton')?.addEventListener('click',()=>{$('#pulseDrawer')?.classList.add('open');renderPulse()});$('#pulseClose')?.addEventListener('click',()=>$('#pulseDrawer')?.classList.remove('open'));document.querySelectorAll('[data-pulse-tab]').forEach(b=>b.addEventListener('click',()=>pulseTab(b.dataset.pulseTab)));$('#pulseDrawer')?.addEventListener('change',e=>{if(e.target?.matches?.('input[data-ai]'))changeAIControl(e.target)})}'''
src,n=re.subn(r"function wireUI\(\)\{.*?\}\nfunction syncButtons",wire+"\nfunction syncButtons",src,count=1,flags=re.S)
if n!=1:raise SystemExit('wireUI anchor not found')

